Translate("frFR", "gryphon-master-talonaxe", {
	title = "Maître des griffons Talonaxe",
	subtitle = "Maître de la volière du Nid-de-l'Aigle",
	found = "La volière du Nid-de-l'Aigle",
	hint = [=[Montez à la volière du Nid-de-l'Aigle et parlez à son maître.]=],
	allegiance = "Clan Wildhammer",
	aliases = { "Talonaxe" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le maître des griffons Talonaxe tient la grande volière du {link:aerie-peak}Nid-de-l'Aigle{/link}. Il connaît chaque griffon des troupeaux du clan et chaque chevaucheur qui en a jamais monté un. Il se souvient de leurs noms bien après que les autres les ont oubliés, et il garde une tendresse particulière pour la {link:explorers-league}Ligue des explorateurs{/link}, car son propre père était parmi les nains qui mirent au jour {link:uldaman}Uldaman{/link} les premiers.]=],
		},
		{
			title = "Importance",
			text = [=[Les griffons sont la force des Wildhammer, et Talonaxe est leur gardien. Quand un griffon est perdu, tout le clan le ressent. Quand l'héritier du plus grand griffon de la volière disparut, c'est Talonaxe qui refusa de prendre du repos avant qu'on ait retrouvé le petit. Son histoire montre combien le sort des nains est étroitement lié à celui de leurs bêtes.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dresse les griffons du {link:aerie-peak}Nid-de-l'Aigle{/link} et leur attribue leurs chevaucheurs.
• Il prêta un jour son meilleur chevaucheur, {link:rhapsody-shindigger}Rhapsody Shindigger{/link}, à l'explorateur {link:brohann-caskbelly}Brohann Caskbelly{/link} pour un vol au-dessus du {link:swamp-of-sorrows}Marais des Chagrins{/link}.
• Il renvoya Rhapsody quand la boisson s'empara de lui après ce vol.
• Il mena la recherche de Sharpbeak, des cages des {link:witherbark-trolls}Witherbark{/link} jusqu'à l'{link:the-altar-of-zul}Autel de Zul{/link}.
• Il fit appel à un devin Wildhammer des {link:blasted-lands}Terres foudroyées{/link} quand toutes les autres recherches eurent échoué.]=],
		},
	},
	chapters = {
		{
			title = "Le chevaucheur tombé",
			hint = [=[Apprenez du maître des griffons ce qu'il advint du chevaucheur envoyé avec Brohann.]=],
			text = [=[Talonaxe se souvint aussitôt du vol. Il avait envoyé son meilleur chevaucheur voler avec {link:brohann-caskbelly}Brohann{/link} au-dessus du marais, à la recherche d'un temple englouti. Ce chevaucheur était {link:rhapsody-shindigger}Rhapsody Shindigger{/link}, et personne dans la volière ne volait comme lui. Mais Rhapsody revint de ce vol ébranlé et assoiffé, et sa soif ne fit que croître. À la fin, le maître de la volière dut le renvoyer.]=],
		},
		{
			title = "L'héritier perdu",
			hint = [=[Fouillez les villages trolls et l'Autel de Zul à la recherche d'un jeune griffon disparu.]=],
			text = [=[Sharpbeak, l'héritier du plus puissant griffon de la volière, disparut alors qu'il chassait avec ses parents. Talonaxe était sûr que des trolls l'avaient pris. On fouilla les cages des villages {link:witherbark-trolls}Witherbark{/link}, et on les trouva vides. On fouilla ensuite l'{link:the-altar-of-zul}Autel de Zul{/link}, où les Vilebranch font leurs sacrifices. Le jeune griffon n'y était pas non plus, et Talonaxe ne savait s'il devait s'affliger ou se réjouir.]=],
		},
		{
			title = "Une plume et un devin",
			hint = [=[Portez une plume du nid de Sharpbeak au devin de Rempart-du-Néant.]=],
			text = [=[Toutes les pistes s'étant refroidies, Talonaxe se tourna vers {link:thadius-grimshade}Thadius Grimshade{/link}. Grimshade avait quitté le {link:aerie-peak}Nid-de-l'Aigle{/link} des années plus tôt pour chercher un savoir plus sombre, mais Talonaxe le disait toujours Wildhammer dans l'âme. Une plume du nid où le jeune griffon avait dormi fut envoyée à la tour du devin, afin qu'il puisse suivre son fil jusqu'à son propriétaire.]=],
		},
		{
			title = "La cage sur la falaise",
			hint = "Ramenez chez lui le jeune griffon détenu par les Vilebranch.",
			text = [=[La divination de {link:thadius-grimshade}Grimshade{/link} trouva Sharpbeak dans une cage haut perchée sur une falaise de {link:jintha-alor}Jintha'Alor{/link}. La clé pendait à la ceinture de l'immonde prêtresse {link:vile-priestess-hexx}Hexx{/link}. Les Wildhammer ne pouvaient le supporter. La prêtresse tomba, la cage fut ouverte, et Sharpbeak rentra auprès de ses parents. Talonaxe les regarda s'affairer autour de leur petit, et les yeux du vieux {link:dwarves}nain{/link} n'étaient pas secs.]=],
		},
	},
	mentions = {
		{ text = "Le maître des griffons Talonaxe" },
		{ text = "{link:rhapsody-shindigger}Rhapsody Shindigger{/link}" },
		{ text = "Les cages des {link:witherbark-trolls}Witherbark{/link}" },
		{ text = "{link:the-altar-of-zul}L'Autel de Zul{/link}" },
		{ text = "{link:thadius-grimshade}Thadius Grimshade{/link}" },
		{ text = "Retour dans les {link:the-hinterlands}Hinterlands{/link}" },
		{ text = "Sauver Sharpbeak" },
	},
	bonds = {
		{ id = "falstad-wildhammer", name = "Falstad Wildhammer", note = "son haut thane" },
		{ id = "rhapsody-shindigger", name = "Rhapsody Shindigger", note = "autrefois son meilleur chevaucheur" },
		{ id = "sharpbeak", name = "Sharpbeak", note = "l'héritier perdu de la volière" },
		{ id = "thadius-grimshade", name = "Thadius Grimshade", note = "un Wildhammer dans l'âme" },
		{ id = "vile-priestess-hexx", name = "Immonde prêtresse Hexx", note = "détenait la clé de la cage de Sharpbeak" },
		{ id = "brohann-caskbelly", name = "Brohann Caskbelly", note = "emprunta son meilleur chevaucheur" },
	},
})

