Translate("frFR", "rhapsody-shindigger", {
	title = "Rhapsody Shindigger",
	subtitle = "Ancien chevaucheur de griffon du Nid-de-l'Aigle",
	found = "Camp de Shindigger",
	hint = [=[Trouvez l'ancien chevaucheur de griffon qui brasse sa propre boisson à l'est du Nid-de-l'Aigle.]=],
	allegiance = "Clan Wildhammer (renvoyé)",
	aliases = { "Rhapsody" },
	sections = {
		{
			title = "Résumé",
			text = [=[Rhapsody Shindigger était jadis le meilleur chevaucheur de griffon du {link:aerie-peak}Nid-de-l'Aigle{/link}. Il vola avec l'explorateur {link:brohann-caskbelly}Brohann Caskbelly{/link} au-dessus du {link:swamp-of-sorrows}Marais des Chagrins{/link} à la recherche d'un temple englouti. Après ce vol, il se mit à boire, et la volière le renvoya. Il tient désormais son propre camp de brassage, et il hoquette à chaque phrase.]=],
		},
		{
			title = "Importance",
			text = [=[Rhapsody seul connaissait la vérité que cherchait {link:brohann-caskbelly}Brohann{/link}. Le temple des Atal'ai repose sous le marais, et il l'avait vu de ses propres yeux.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il but un tonnelet entier de stout avant le vol au-dessus du marais.
• Il tomba de son griffon dans l'eau, fut entraîné vers le fond, et se retrouva parmi des trolls dans un temple englouti.
• Il s'échappa avec un fragment de tablette atal'ai.]=],
		},
	},
	chapters = {
		{
			title = "Un remontant",
			hint = [=[Apportez à l'ancien chevaucheur ce qu'il lui faut pour raconter son histoire.]=],
			text = [=[Rhapsody refusait de parler du marais à jeun. Seule une boisson brassée avec les gésiers et les foies de bêtes de la lointaine {link:kalimdor}Kalimdor{/link} pouvait lui délier la langue. Alors l'histoire sortit enfin. Le chevaucheur était tombé dans le marais, avait coulé jusque dans le temple des {link:temple-of-atal-hakkar}Atal'ai{/link}, et en était ressorti à la nage avec une relique troll à la main. Le temple que {link:brohann-caskbelly}Brohann{/link} cherchait était réel.]=],
		},
	},
	mentions = {
		{ text = "Rhapsody Shindigger" },
		{ text = "Le cocktail kalimdorien de Rhapsody" },
		{ text = "Le récit de Rhapsody" },
	},
	bonds = {
		{ id = "gryphon-master-talonaxe", name = "Maître des griffons Talonaxe", note = "le renvoya" },
		{ id = "brohann-caskbelly", name = "Brohann Caskbelly", note = "vola avec lui au-dessus du marais" },
		{ id = "gilveradin-sunchaser", name = "Gilveradin Sunchaser", note = "partage son camp" },
	},
})

Translate("frFR", "gilveradin-sunchaser", {
