		},
	},
	mentions = {
		{ text = "Récupération de l'ondée" },
		{ text = "Une situation collante" },
		{ text = "Livraison de l'ondée" },
	},
	bonds = {
		{ id = "rhapsody-shindigger", name = "Rhapsody Shindigger", note = "partage son camp" },
	},
})

