Translate("frFR", "atal-ai-exile", {
	title = "Exilé atal'ai",
	subtitle = "Prêtre paria des Atal'ai",
	found = "Près de Shadra'Alor, parmi les Witherbark",
	hint = [=[Trouvez le prêtre paria qui vit parmi les Witherbark près de Shadra'Alor.]=],
	allegiance = "Aucune (exilé des Atal'ai)",
	sections = {
		{
			title = "Résumé",
			text = [=[L'exilé atal'ai était jadis un prêtre des Atal'ai, la secte troll du temple englouti du {link:swamp-of-sorrows}Marais des Chagrins{/link}. Quand le prophète {link:jammal-an-the-prophet}Jammal'an{/link} prédit que l'invocation d'{link:hakkar}Hakkar{/link} rendrait les Atal'ai immortels, ce prêtre prêcha la prudence. Pour cela, il fut déclaré infidèle et chassé. La sentence de son peuple l'envoya au nord vivre parmi les {link:witherbark-trolls}Witherbark{/link}, un sort que les Atal'ai jugent pire que la mort.]=],
		},
		{
			title = "Importance",
			text = [=[L'exilé est une rare voix du doute au sein du culte d'{link:hakkar}Hakkar{/link}. Il croit que la prophétie de {link:jammal-an-the-prophet}Jammal'an{/link} détruira son peuple, et il connaît assez bien les rites d'invocation pour les craindre.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il avertit {link:jammal-an-the-prophet}Jammal'an{/link} que la prophétie n'était peut-être rien de plus qu'une manipulation.
• Il jugea inoffensifs les objets atal'ai qu'on lui apporta du marais, mais mit en garde contre ce que le rituel pourrait faire s'il était achevé.
• Il cherche à venger son exil.]=],
		},
	},
	chapters = {
		{
			title = "La tête du prophète",
			hint = "Vengez l'exilé du prophète qui l'a chassé.",
			text = [=[L'exilé voulait la tête de {link:jammal-an-the-prophet}Jammal'an{/link}. Il espérait que son peuple serait libéré une fois le prophète disparu, et qu'il pourrait rentrer chez lui. Quand ce fut fait, il rendit grâce, et il porta le deuil. Les fausses visions de Jammal'an avaient déjà mené les Atal'ai à leur perte. Il ne lui restait aucun foyer où retourner.]=],
		},
	},
	mentions = {
		{ text = "L'exilé atal'ai" },
		{ text = "Retour auprès de Fel'Zerul" },
		{ text = "{link:jammal-an-the-prophet}Jammal'an le Prophète{/link}" },
	},
	bonds = {
		{ id = "fel-zerul", name = "Fel'Zerul", note = "lui envoya les objets atal'ai" },
	},
})

Translate("frFR", "sharpbeak", {
	title = "Sharpbeak",
	subtitle = "Héritier de la volière du Nid-de-l'Aigle",
	found = "Une cage sur une falaise près de Jintha'Alor",
