		},
		{
			title = "Hauts faits",
			text = [=[• Il fut enlevé par des trolls et mis en cage près de {link:jintha-alor}Jintha'Alor{/link}.
• Il fut libéré après la chute de l'immonde prêtresse {link:vile-priestess-hexx}Hexx{/link}, et il retourna auprès de ses parents à la volière.]=],
		},
	},
	mentions = {
		{ text = "Les cages des {link:witherbark-trolls}Witherbark{/link}" },
		{ text = "Sauver Sharpbeak" },
