Translate("frFR", "vile-priestess-hexx", {
	title = "Immonde prêtresse Hexx",
	subtitle = "Grande prêtresse des Vilebranch",
	found = "Le sommet de Jintha'Alor",
	hint = [=[Affrontez la grande prêtresse qui règne sur le sommet de Jintha'Alor.]=],
	allegiance = "Trolls Vilebranch",
	aliases = { "Hexx" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'immonde prêtresse Hexx est la grande prêtresse des trolls {red:vilebranch-trolls}Vilebranch{/red}. Elle règne sur le sommet de {link:jintha-alor}Jintha'Alor{/link} avec sa garde d'élite, les Aman'zasi. Ses sombres tissages emplissent des récipients de sang corrompu à travers la cité, et par eux la puissance du dieu du sang {link:hakkar}Hakkar{/link} pousse son peuple à une férocité folle qui ne connaît pas la mort.]=],
		},
		{
			title = "Importance",
			text = [=[Hexx est la raison pour laquelle les Vilebranch sont plus qu'une tribu sauvage. Par elle, ils sont devenus des serviteurs d'{link:hakkar}Hakkar{/link}, prenant des captifs chez tous les peuples des {link:the-hinterlands}Hinterlands{/link} pour les sacrifier. {link:dwarves}Nains{/link} et trolls souffrent également de son règne. Le {link:aerie-peak}Nid-de-l'Aigle{/link} comme le {link:revantusk-village}Village des Revantusk{/link} ont mis sa tête à prix. Les Revantusk préviennent que même si elle tombe, une autre se lèvera à sa place.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle prépara l'ancien {link:primal-torntusk}Torntusk{/link} des {link:revantusk-village}Revantusk{/link} pour le sacrifier à {link:hakkar}Hakkar{/link}.
• Elle détenait la clé de la cage de Sharpbeak, le jeune griffon du {link:aerie-peak}Nid-de-l'Aigle{/link}.
• Elle renforça les Vilebranch avec le sang corrompu du dieu sans visage.
• Elle commande les Aman'zasi, la garde d'élite de {link:jintha-alor}Jintha'Alor{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La prêtresse du dieu du sang",
			hint = "Brisez le pouvoir des récipients corrompus de Jintha'Alor.",
			text = [=[Les {link:revantusk-village}Revantusk{/link} apprirent où les Vilebranch puisaient leur force. Des récipients de sang corrompu se dressaient à travers {link:jintha-alor}Jintha'Alor{/link}, tissés de la magie d'Hexx et emplis de la puissance d'{link:hakkar}Hakkar{/link}. Quand les récipients furent volés et purifiés, la folie des Vilebranch s'apaisa. Elle ne cessa pas.]=],
		},
		{
			title = "La chute de la prêtresse",
			hint = "Faites justice de l'immonde prêtresse.",
			text = [=[Sur ordre de {link:primal-torntusk}Primal Torntusk{/link}, une récompense fut offerte pour la mort d'Hexx et de ses gardes aman'zasi. Les nains du {link:aerie-peak}Nid-de-l'Aigle{/link} voulaient eux aussi sa mort, car elle détenait la clé de la cage de Sharpbeak. La prêtresse tomba au sommet de sa cité. Les Vilebranch chancelèrent sous le coup, et leurs ennemis savaient qu'ils ne resteraient pas longtemps sans chef.]=],
		},
	},
	mentions = {
		{ text = "L'ancien {link:primal-torntusk}Torntusk{/link} enlevé !" },
		{ text = "Sombres récipients" },
		{ text = "Recherchés : l'immonde prêtresse Hexx et ses sbires" },
		{
			text = [=[Retour dans les {link:the-hinterlands}Hinterlands{/link}, la parole du devin]=],
		},
		{ text = "Sauver Sharpbeak" },
	},
	bonds = {
		{ id = "primal-torntusk", name = "Primal Torntusk", note = "mit sa tête à prix" },
		{ id = "elder-torntusk", name = "Ancien Torntusk", note = "son captif" },
		{ id = "sharpbeak", name = "Sharpbeak", note = "son captif" },
		{ id = "hitah-ya-the-keeper", name = "Hitah'ya la Gardienne", note = "détient les clés de ses captifs" },
	},
})

