Translate("frFR", "shadra", {
	title = "Shadra",
	subtitle = "La reine du venin",
	found = "Appelée à l'autel de Shadra'Alor",
	hint = [=[Apprenez le vrai nom du dieu araignée des Witherbark, et prononcez-le à son autel.]=],
	allegiance = "Trolls Witherbark",
	sections = {
		{
			title = "Résumé",
			text = [=[Shadra est le dieu araignée des trolls {link:witherbark-trolls}Witherbark{/link}. Ils l'appellent la reine du venin, et d'elle vient le venin le plus puissant qu'ils connaissent. Elle ne marche pas parmi ses fidèles. Elle ne vient que lorsque son vrai nom est lu à voix haute à son autel de {link:shadra-alor}Shadra'Alor{/link}, et ce nom est si lourd de pouvoir que les sages ne le prononcent qu'en murmurant.]=],
		},
		{
			title = "Importance",
			text = [=[Shadra est le cœur de la foi des {link:witherbark-trolls}Witherbark{/link}. Son nom fut écrit il y a longtemps sur une tablette dans la cité troll de {red:zul-farrak}Zul'Farrak{/red}, loin de l'autre côté de la mer. La {link:royal-apothecary-society}Société royale des apothicaires{/link} des {link:forsaken}Réprouvés{/link} convoite son venin plus que tout autre.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle donne son venin aux {link:witherbark-trolls}Witherbark{/link}, qui le conservent en bouteilles dans leurs villages.
• Elle fut appelée à son autel par un sort d'invocation composé par {link:master-gadrin}maître Gadrin{/link} des {link:darkspear-trolls}Darkspear{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La reine du venin",
			hint = "Invoquez le dieu araignée à Shadra'Alor.",
			text = [=[L'{link:apothecary-lydon}apothicaire Lydon{/link} de {link:tarren-mill}Moulin-de-Tarren{/link} voulait le venin le plus frais des {link:witherbark-trolls}Witherbark{/link}, et aucune araignée ordinaire ne ferait l'affaire. {link:master-gadrin}Maître Gadrin{/link} savait d'où il venait. D'une tablette de Zul'Farrak vint son vrai nom, et de Gadrin vint un parchemin capable de l'appeler. À l'autel de {link:shadra-alor}Shadra'Alor{/link}, les mots furent lus, et la reine du venin répondit. Son venin partit pour Moulin-de-Tarren, et de là pour l'{link:the-apothecarium}Apothicarium{/link} d'{link:undercity}Undercity{/link}.]=],
		},
	},
	mentions = {
		{ text = "Bouteilles de venin" },
		{ text = "Poche de venin intacte" },
		{ text = "Consulter maître Gadrin" },
		{ text = "Le dieu araignée" },
		{ text = "Invoquer Shadra" },
		{ text = "Du venin pour {link:undercity}Undercity{/link}" },
	},
	bonds = {
		{ id = "master-gadrin", name = "Maître Gadrin", note = "écrivit le sort qui l'appelle" },
		{ id = "apothecary-lydon", name = "Apothicaire Lydon", note = "chercha son venin" },
		{ id = "master-apothecary-faranell", name = "Maître apothicaire Faranell", note = "reçut son venin" },
	},
})

Translate("frFR", "primal-torntusk", {
	title = "Primal Torntusk",
	subtitle = "Chef du Village des Revantusk",
	found = "Village des Revantusk",
	hint = "Parlez à la trolle qui commande le Village des Revantusk.",
	allegiance = "Trolls Revantusk · Horde",
	aliases = { "Torntusk" },
	sections = {
		{
			title = "Résumé",
			text = [=[Primal Torntusk commande le {link:revantusk-village}Village des Revantusk{/link}. Ses ordres sont donnés en son propre nom, et ses primes sont affichées à la vue de tous. C'est une guerrière des {red:revantusk-trolls}Revantusk{/red} et une sage de son peuple, et elle connaît assez bien les arts sombres des Vilebranch pour les défaire. Quand les Vilebranch vinrent dans la nuit et emportèrent son compagnon, elle ne désespéra pas. Elle appela à l'aide et partit en guerre.]=],
		},
		{
			title = "Importance",
			text = [=[Torntusk tient la tête de pont de la {link:horde}Horde{/link} dans les {link:the-hinterlands}Hinterlands{/link}. Son village est petit et entouré d'ennemis : les Vilebranch au nord et à l'ouest, les bêtes sauvages des collines, et les Wildhammer à l'autre bout du pays. Sous sa conduite, les {link:revantusk-village}Revantusk{/link} sont devenus l'ennemi le plus obstiné des Vilebranch. Elle seule parmi eux semble comprendre que le véritable ennemi n'est pas la tribu mais le dieu qu'elle sert.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle rallia son village après qu'un raid des Vilebranch eut emporté son compagnon et son capitaine de la garde.
• Elle purifia les récipients de sang corrompu emportés de {link:jintha-alor}Jintha'Alor{/link}.
• Elle mit à prix la tête de l'immonde prêtresse {link:vile-priestess-hexx}Hexx{/link} et de sa garde aman'zasi.
• Elle cherche un nouveau capitaine de la garde pour remplacer Malkhor, tombé au combat.]=],
		},
	},
	chapters = {
		{
			title = "Le raid de minuit",
			hint = [=[Délivrez de Jintha'Alor le compagnon de la cheffe des Revantusk.]=],
			text = [=[Les Vilebranch vinrent au milieu de la nuit et prirent vivant l'ancien Torntusk. Les espions des {link:revantusk-village}Revantusk{/link} apprirent qu'il était retenu au sommet de {link:jintha-alor}Jintha'Alor{/link} et qu'{link:vile-priestess-hexx}Hexx{/link} comptait l'offrir à {link:hakkar}Hakkar{/link}. Torntusk dit sans détour que son village ne pourrait supporter une telle perte. Les fers furent brisés, l'ancien rentra chez lui, et la dette des Revantusk fut grande.]=],
		},
		{
			title = "Desserrer l'étreinte",
			hint = [=[Volez les récipients corrompus de Jintha'Alor pour Primal Torntusk.]=],
			text = [=[Torntusk comprit que les Vilebranch ne combattaient pas avec leur propre force. Le sang de leurs récipients portait la puissance du dieu sans visage, et il les rendait fous. Quand on lui apporta les récipients, elle en retira la corruption. L'étreinte du {link:hakkar}dieu du sang{/link} se desserra. Elle avertit son peuple que ce n'était que pour un temps.]=],
		},
		{
			title = "Un capitaine pour les Revantusk",
			hint = [=[Montrez-vous digne du commandement de la garde des Revantusk.]=],
			text = [=[Malkhor mort, le poste de capitaine de la garde restait vacant. Torntusk lança un appel à quiconque voudrait éclaircir les rangs des guerriers, des chasseurs des ombres, des buveurs de sang et des mange-âmes Vilebranch. Ceux qui répondirent furent remerciés et récompensés. Le choix lui-même, dit-elle, attendrait l'année suivante.]=],
		},
	},
	mentions = {
		{ text = "L'ancien Torntusk enlevé !" },
		{ text = "Retour auprès de Primal Torntusk" },
		{ text = "Sombres récipients" },
		{
			text = [=[Recherchés : l'immonde prêtresse {link:vile-priestess-hexx}Hexx{/link} et ses sbires]=],
		},
		{
			text = [=[Poste à pourvoir : capitaine de la garde du {link:revantusk-village}Village des Revantusk{/link}]=],
		},
	},
	bonds = {
		{ id = "elder-torntusk", name = "Ancien Torntusk", note = "son compagnon" },
		{ id = "huntsman-markhor", name = "Veneur Markhor", note = "frère de son capitaine tombé" },
		{ id = "vile-priestess-hexx", name = "Immonde prêtresse Hexx", note = "son ennemie" },
		{ id = "falstad-wildhammer", name = "Falstad Wildhammer", note = "thane des nains que son peuple hait" },
	},
})

